/*
 * prog47_circular_queue.c
 *
 * Re‑implementation of the original program whose behaviour was
 * discovered by reverse‑engineering the obfuscated binary.
 *
 * The program implements a circular queue of capacity 5 that is
 * manipulated by command‑line arguments.
 *
 *   E<number>   – enqueue the signed decimal integer <number>
 *                 (prints "ENQ %ld" on success, "FULL" if the queue
 *                 is already full, "ERR" if the number cannot be parsed)
 *
 *   D           – dequeue the element at the front of the queue
 *                 (prints "DEQ %ld" on success, "EMPTY" if the queue is empty)
 *
 *   F           – show the element at the front without removing it
 *                 (prints "FRONT %ld" on success, "EMPTY" if the queue is empty)
 *
 *   (no arguments) – prints a single line "NOOP"
 *
 * Any other argument (including malformed commands) results in
 * printing "ERR".
 *
 * The observable output (stdout) of this program matches exactly the
 * original binary for all possible inputs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define CAPACITY 5

static long items[CAPACITY];
static int head = 0;   /* index of the first element */
static int count = 0;  /* number of elements currently stored */

/* Helper: advance an index modulo CAPACITY */
static int next_index(int idx)
{
    return (idx + 1) % CAPACITY;
}

/* Enqueue a value; returns 0 on success, 1 if the queue is full */
static int enqueue(long value)
{
    if (count == CAPACITY)
        return 1;                     /* full */

    items[(head + count) % CAPACITY] = value;
    ++count;
    return 0;
}

/* Dequeue a value; caller must ensure the queue is non‑empty */
static long dequeue(void)
{
    long v = items[head];
    head = next_index(head);
    --count;
    return v;
}

/* Return the value at the front; caller must ensure the queue is non‑empty */
static long front(void)
{
    return items[head];
}

int main(int argc, char *argv[])
{
    /* No arguments – the original program printed a single "NOOP". */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        const char *cmd = argv[i];

        if (cmd[0] == 'E' && cmd[1] != '\0') {
            /* ENQ command – parse the number after the leading 'E' */
            char *endptr = NULL;
            errno = 0;
            long val = strtol(cmd + 1, &endptr, 10);

            if (endptr == cmd + 1 || *endptr != '\0' || errno != 0) {
                puts("ERR");
                continue;
            }

            if (enqueue(val) == 0) {
                printf("ENQ %ld\n", val);
            } else {
                puts("FULL");
            }
        }
        else if (strcmp(cmd, "D") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                long v = dequeue();
                printf("DEQ %ld\n", v);
            }
        }
        else if (strcmp(cmd, "F") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                long v = front();
                printf("FRONT %ld\n", v);
            }
        }
        else {
            /* Any unrecognised command results in an error. */
            puts("ERR");
        }
    }

    return 0;
}
